public class InnerSourceEndpointSourceEndpointConfigurationFactory(Action<Humidifier.MediaConnect.SourceEndpointTypes.SourceEndpointConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.SourceEndpointTypes.SourceEndpointConfiguration>
{

    internal InnerSourceEndpointStandardSourceEndpointConfigurationFactory StandardFactory { get; set; }

    internal InnerSourceEndpointRouterOutputSourceEndpointConfigurationFactory RouterOutputFactory { get; set; }

    protected override Humidifier.MediaConnect.SourceEndpointTypes.SourceEndpointConfiguration Create()
    {
        var sourceEndpointConfigurationResult = CreateSourceEndpointConfiguration();
        factoryAction?.Invoke(sourceEndpointConfigurationResult);

        return sourceEndpointConfigurationResult;
    }

    private Humidifier.MediaConnect.SourceEndpointTypes.SourceEndpointConfiguration CreateSourceEndpointConfiguration()
    {
        var sourceEndpointConfigurationResult = new Humidifier.MediaConnect.SourceEndpointTypes.SourceEndpointConfiguration();

        return sourceEndpointConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.SourceEndpointTypes.SourceEndpointConfiguration result)
    {
        base.CreateChildren(result);

        result.Standard ??= StandardFactory?.Build();
        result.RouterOutput ??= RouterOutputFactory?.Build();
    }

} // End Of Class

